def bump_major(self):
    """Return a new VersionInfo with major incremented and minor/patch/reset to 0."""
    return VersionInfo(
        self.major + 1,
        0,
        0,
        prerelease=None,
        build=None,
    )

def bump_minor(self):
    """Return a new VersionInfo with minor incremented and patch reset to 0."""
    return VersionInfo(
        self.major,
        self.minor + 1,
        0,
        prerelease=self.prerelease,
        build=self.build,
    )

def bump_patch(self):
    """Return a new VersionInfo with patch incremented."""
    return VersionInfo(
        self.major,
        self.minor,
        self.patch + 1,
        prerelease=self.prerelease,
        build=self.build,
    )

def bump_prerelease(self):
    """Return a new VersionInfo with prerelease incremented."""
    if self.prerelease is None:
        raise ValueError("Cannot bump prerelease on a release version")
    prerelease = self.prerelease.split(".")
    try:
        prerelease[-1] = str(int(prerelease[-1]) + 1)
    except ValueError:
        pass  # Keep as-is if it's not numeric
    return VersionInfo(
        self.major,
        self.minor,
        self.patch,
        prerelease=".".join(prerelease),
        build=self.build,
    )

def bump_build(self):
    """Return a new VersionInfo with build incremented."""
    if self.build is None:
        raise ValueError("Cannot bump build on a version without build metadata")
    build = self.build.split(".")
    try:
        build[-1] = str(int(build[-1]) + 1)
    except ValueError:
        pass  # Keep as-is if it's not numeric
    return VersionInfo(
        self.major,
        self.minor,
        self.patch,
        prerelease=self.prerelease,
        build=".".join(build),
    )

